        "mainEntity": [
          {
            "@type": "Question",
            "name": "Is this really free?",
            "acceptedAnswer": {
              "@type": "Answer",
              "text": "Yes — completely. No account, no watermark, no hidden limits."
            }
          },
          {
            "@type": "Question",
            "name": "Is my JSON uploaded?",
            "acceptedAnswer": {
              "@type": "Answer",
              "text": "No. Everything happens in your browser using native JSON.parse and JSON.stringify. Nothing is sent over the network."
            }
          },
          {
            "@type": "Question",
            "name": "What counts as valid JSON?",
            "acceptedAnswer": {
              "@type": "Answer",
              "text": "Strict JSON per RFC 8259 — double-quoted keys/strings, no trailing commas, no comments, no NaN/Infinity. If your input has those, it will show an error."
            }
          },
          {
            "@type": "Question",
            "name": "What does 'sort keys' do?",
            "acceptedAnswer": {
              "@type": "Answer",
              "text": "It rearranges object keys alphabetically before formatting. Array order is preserved. Useful when you want deterministic output for version control or diffing."
            }
          },
          {
            "@type": "Question",
            "name": "What's the difference between format and minify?",
            "acceptedAnswer": {
              "@type": "Answer",
              "text": "Formatted output adds newlines and indentation for readability. Minified output strips all unnecessary whitespace to produce the smallest valid JSON string."
            }
          },
          {
            "@type": "Question",
            "name": "Why does it say my JSON is invalid when it looks fine?",
            "acceptedAnswer": {
              "@type": "Answer",
              "text": "Common gotchas: single quotes instead of double, trailing commas, comments (// or /* */), unquoted keys, or NaN/Infinity. JSON is stricter than JavaScript object syntax."
            }
          },
          {
            "@type": "Question",
            "name": "Can I paste JSON with a BOM or Windows line endings?",
            "acceptedAnswer": {
              "@type": "Answer",
              "text": "Yes — BOM and CRLF are handled. If you see unexpected errors, try retyping the first character (BOM can be invisible)."
            }
          },
          {
            "@type": "Question",
            "name": "Does it work on mobile?",
            "acceptedAnswer": {
              "@type": "Answer",
              "text": "Yes. The tool is fully responsive and works on iOS Safari and Android Chrome."
            }
          }
        ]
